def T(t,st):return f'<div class="t" style="{st}">{t}</div>'
def im(src,st,cut=False):return f'<img src="{src}" style="position:absolute;{st};object-fit:contain;{"filter:drop-shadow(0 8px 10px #0005)" if cut else "border-radius:3px;box-shadow:0 4px 10px #0005;object-fit:cover"}">'
def F(inner,bg):return f'<div class="frame" style="background:{bg}">{inner}<div class="mk">⌂ devdha.in</div></div>'
glow='text-shadow:0 0 12px #fff9,0 0 34px #7FA6FF99;font-weight:700'
def words(ws,cols=None,top=120,size=64):return T(ws,f'left:0;right:0;text-align:center;top:{top}px;font-size:{size}px;{glow}')
dots=lambda n,on:'<div style="position:absolute;left:0;right:0;bottom:16px;display:flex;justify-content:center;gap:7px">'+''.join(f'<i style="width:8px;height:8px;border-radius:50%;background:{"#111" if i==on else "#1114"}"></i>' for i in range(n))+'</div>'
banner=lambda txt,left,top,w=260:f'<div style="position:absolute;left:{left}px;top:{top}px;width:{w}px;height:44px;background:#8a7f6bcc;color:#fff;font-weight:700;font-size:26px;padding:0 12px;line-height:44px;letter-spacing:1px;box-shadow:0 4px 10px #0004">{txt}</div>'
def browser(inner,left,top,w,h):return f'<div style="position:absolute;left:{left}px;top:{top}px;width:{w}px;height:{h}px;background:#fff;border-radius:8px;box-shadow:0 8px 20px #0a2a5e66;overflow:hidden"><div style="height:24px;background:#0A2A5E;color:#fff;font-size:11px;padding:5px 10px">● ● ●&nbsp;&nbsp; yourshop.in</div>{inner}</div>'
