def wall(c,r):
    from itertools import cycle
    pool=[R('diwali'),R('minimen'),R('prachitam'),R('culturist'),R('posters'),R('clipa'),R('clipb'),C('krishna'),R('desires'),R('atworkpost'),R('clipc'),C('honeycomb'),R('card'),R('clipd'),C('key'),C('mug')]
    w=560/c;h=315/r;o=''
    for i in range(c*r):
        s=pool[(i*5+2)%len(pool)];o+=f'<div style="position:absolute;left:{(i%c)*w+1}px;top:{(i//c)*h+1}px;width:{w-2}px;height:{h-2}px;background:#16336f;overflow:hidden"><img src="{s}" style="width:100%;height:100%;object-fit:{"contain" if "cut" in s else "cover"}"></div>'
    return o
