def card(s):
    rows=''.join(f'<tr><th>{a}</th><td>{b}</td></tr>' for a,b in s['beats'])
    tx=''.join(f'<div><span class="chip">{l}</span> {t}</div>' for l,t in zip(['EN','हिन्दी','मराठी'],s['txt']))
    return f'<div class="card"><div class="cap" style="font-size:12px">S{s["id"]} · {s["t"]} · {s["n"]}</div>{s["fr"]}<table style="margin-top:4px">{rows}<tr><th>Assets</th><td>{s["assets"]}</td></tr></table><div class="l3" style="margin-top:4px">{tx}</div></div>'
